        P([(50, 22), (55, 18), (54, 28)], "light"),                             # tail flame
        E(36, 46, 3, 7, "dark"), E(44, 45, 3, 7, "dark"),                       # far legs
        E(32, 38, 15, 9, "mid"),                                                # body
        E(24, 47, 3, 7, "dark"), E(38, 48, 3, 6, "dark"),                       # near legs
        P([(14, 26), (24, 22), (30, 32), (20, 38)], "mid"),                     # neck
        P([(22, 18), (28, 12), (30, 20), (34, 16), (36, 26), (40, 22), (40, 32), (28, 30)], "light"),  # mane
        E(14, 24, 9, 7, "mid"),                                                 # head
        P([(2, 26), (10, 22), (12, 30), (4, 31)], "mid"),                       # snout
        P([(16, 18), (26, 10), (30, 12), (20, 20)], "dark"),                    # horn
        eye(10, 21),
        Stamp(4, 29, ["0000"]),
        Stamp(2, 25, ["0"]),
