def puddlet():
    # A droplet with a frilled fin-tail and big eyes; bubbles drift above.
    drop = union(ellipse_mask(26, 40, 13, 11), poly_mask([(16, 34), (28, 16), (36, 34)]))
    return [
        P([(36, 40), (52, 30), (50, 40), (54, 48), (38, 48)], "mid"),           # tail fin
        Part(drop, "light"),
        E(26, 46, 9, 4, "mid", outline=False),                                  # belly shade
        E(42, 18, 3, 3, "light"), E(48, 10, 2, 2, "light"),                     # bubbles
        eye(16, 34, big=True), eye(24, 34, big=True),
        Stamp(19, 42, ["0..0", ".00."]),
    ]


